#!/usr/bin/env node
// Compares a freshly generated component manifest against the previously
// committed one and fails when components disappear without being declared.
//
//   node scripts/diff-manifest.mjs <new-manifest> <previous-manifest>
//
// Get the previous version from git:
//   git show HEAD:data/component-manifest.json > /tmp/prev-manifest.json
//
// Why this exists: a manifest is generated by a script an agent rewrites
// each run, so a changed file glob can silently drop whole component
// families. It happened twice — a non-recursive glob hid every component
// living in a subdirectory (DataTable, DatePicker), and nothing downstream
// could tell, because coverage is measured against the manifest itself.
// A shrinking manifest must be a loud event, not a quiet one.
//
// Exits 1 if any component was removed. Additions are reported, never fail.

import { readFileSync, existsSync } from "node:fs";

const [newPath, prevPath] = process.argv.slice(2);
if (!newPath || !prevPath) {
  console.error("usage: node scripts/diff-manifest.mjs <new-manifest> <previous-manifest>");
  process.exit(2);
}

function load(p, label) {
  if (!existsSync(p)) {
    console.error(`ERROR: ${label} (${p}) not found`);
    process.exit(2);
  }
  let raw;
  try {
    raw = JSON.parse(readFileSync(p, "utf8"));
  } catch (e) {
    console.error(`ERROR: ${label} (${p}) is not valid JSON: ${e.message}`);
    process.exit(2);
  }
  let root = raw.components ?? raw;
  if (Array.isArray(root)) {
    root = Object.fromEntries(root.map((e) => [e.name ?? e.component ?? e.export, e]));
  }
  const out = new Map();
  for (const [name, def] of Object.entries(root)) {
    if (!name || !def || typeof def !== "object") continue;
    out.set(name, { role: def.role === "part" ? "part" : "root", file: def.file ?? "" });
  }
  return out;
}

const next = load(newPath, "new manifest");
const prev = load(prevPath, "previous manifest");

const removed = [...prev.keys()].filter((c) => !next.has(c));
const added = [...next.keys()].filter((c) => !prev.has(c));
const rerolled = [...next.keys()].filter((c) => prev.has(c) && prev.get(c).role !== next.get(c).role);

if (added.length) {
  console.log(`ADDED (${added.length}):`);
  for (const c of added.sort()) console.log(`  + ${c} [${next.get(c).role}] ${next.get(c).file}`);
  console.log();
}
if (rerolled.length) {
  console.log(`ROLE CHANGED (${rerolled.length}):`);
  for (const c of rerolled.sort()) console.log(`  ~ ${c}: ${prev.get(c).role} -> ${next.get(c).role}`);
  console.log();
}
if (removed.length) {
  console.log(`REMOVED (${removed.length}):`);
  for (const c of removed.sort()) console.log(`  - ${c} [${prev.get(c).role}] ${prev.get(c).file}`);
  console.log();
  console.log(
    "ERROR: components present in the previous manifest are missing from the new one.\n" +
      "A component only disappears legitimately when it was deleted from the kit. If the kit\n" +
      "still has it, the extractor's file discovery regressed — check the glob recurses into\n" +
      "subdirectories — and fix that before regenerating the library, because coverage is\n" +
      "measured against this file and cannot require what it cannot see."
  );
}

console.log(`previous: ${prev.size} components, new: ${next.size} components`);
process.exit(removed.length ? 1 : 0);
